  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "target_relation": "different",
      "reference_claim_ids": [
        "R1.S1"
      ],
      "reference_evidence": "The robot lifts both feet, not just one.",
      "candidate_evidence": "Flicker and morphing in the red emblem area on the robot's chest.",
      "basis": "explicit_separation",
      "reason_ko": "R1은 로봇의 양발을 들어올리는 하체 동작 이상을 다루는 반면, C2는 가슴의 빨간 엠블럼 부위에서 발생하는 깜빡임 및 모핑 이상을 다루므로 대상 부위와 이상 현상이 명확히 구분됩니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "target_relation": "same",
      "reference_claim_ids": [
        "R1.S1"
      ],
      "reference_evidence": "The robot lifts both feet, not just one.",
      "candidate_evidence": "The robot's dance cycle consists of repetitive back-and-forth steps that exhibit slight motion jumps and unnatural mechanical jerking at transition phases.",
      "basis": "explicit_separation",
      "reason_ko": "R1은 한 발 대신 양발을 모두 들어 올리는 명시적인 다리 동작 이상을 서술하지만, C3은 앞뒤 반복 스텝 중 전환 단계에서 발생하는 모션 점프와 부자연스러운 기계적 덜컥거림을 서술하고 있어 서로 다른 구체적 결함을 지적하고 있습니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C4",
      "target_relation": "same",
      "reference_claim_ids": [
        "R1.S1"
      ],
      "reference_evidence": "The robot lifts both feet, not just one.",
      "candidate_evidence": "프롬프트는 팔을 위아래로 움직이며 춤추는 동작을 요구했으나, 로봇은 주로 다리를 들고 좌우로 흔들릴 뿐 팔의 상하 움직임 중심의 춤을 추지 않음",
      "basis": "explicit_separation",
      "reason_ko": "R1은 한 발이 아닌 양발을 동시에 들어 올리는 동작 자체를 이상 현상으로 지적하지만, C4는 팔의 상하 움직임이 없다는 프롬프트 불일치를 핵심 결함으로 지적하며 다리를 드는 것은 수행된 동작의 배경으로 언급하고 있어 두 결함이 명확히 구별됩니다."
    }
  ]
}

